final class MobilePolish {
    static void sections(MainActivity a){
        ScrollView scroll=new ScrollView(a);LinearLayout list=a.column();list.setPadding(a.dp(16),a.dp(8),a.dp(16),a.dp(16));scroll.addView(list);
        AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Ваши разделы").setView(scroll).setNegativeButton("Закрыть",null).create();
        for(int n=0;n<MainActivity.SECTIONS.length;n+=2){LinearLayout row=new LinearLayout(a);for(int k=n;k<Math.min(n+2,MainActivity.SECTIONS.length);k++){final int section=k;LinearLayout card=a.column();card.setPadding(a.dp(14),a.dp(16),a.dp(14),a.dp(16));card.setMinimumHeight(a.dp(96));card.setBackground(a.surface(k==a.tab?0xff25433c:MainActivity.PANEL,18,true));card.setFocusable(true);card.setContentDescription(MainActivity.SECTIONS[k]);ImageView icon=new ImageView(a);icon.setImageResource(MainActivity.ICONS[k]);icon.setImageTintList(ColorStateList.valueOf(MainActivity.TEAL));card.addView(icon,new LinearLayout.LayoutParams(a.dp(24),a.dp(24)));TextView title=a.label(MainActivity.SECTIONS[k],15);title.setTextIsSelectable(false);card.addView(title);card.setOnClickListener(v->{dialog.dismiss();a.show(section);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(a.dp(4),a.dp(4),a.dp(4),a.dp(4));row.addView(card,p);}list.addView(row);}
        dialog.show();dialog.getWindow().setLayout(-1,(int)(a.getResources().getDisplayMetrics().heightPixels*.78));list.setAlpha(0);list.setTranslationY(a.dp(18));list.animate().alpha(1).translationY(0).setDuration(280).start();
    }
    static void categories(MainActivity a,Spinner selected,String[] labels){HorizontalScrollView scroll=new HorizontalScrollView(a);scroll.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(a);for(int n=0;n<labels.length;n++){final int index=n;Button chip=a.button(labels[n],()->{selected.setSelection(index);for(int k=0;k<row.getChildCount();k++){Button b=(Button)row.getChildAt(k);b.setBackground(a.surface(k==index?MainActivity.TEAL:MainActivity.PANEL,18,true));b.setTextColor(k==index?MainActivity.BG:MainActivity.WHITE);}});boolean active=selected.getSelectedItemPosition()==n;chip.setBackground(a.surface(active?MainActivity.TEAL:MainActivity.PANEL,18,true));chip.setTextColor(active?MainActivity.BG:MainActivity.WHITE);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.setMargins(0,0,a.dp(8),0);row.addView(chip,p);}scroll.addView(row);a.page.addView(scroll);selected.setVisibility(View.GONE);}
    static String clothing(JSONObject data){JSONObject current=data.optJSONObject("current");double temperature=current==null?Double.NaN:current.optDouble("apparent_temperature",current.optDouble("temperature_2m",Double.NaN));if(!Double.isFinite(temperature))return "Температура пока неизвестна — обновите прогноз.";String text=temperature<0?"Тёплая куртка, шапка и перчатки.":temperature<10?"Куртка и тёплый слой под ней.":temperature<18?"Лёгкая куртка или свитер.":temperature<25?"Лёгкая одежда; вечером может пригодиться дополнительный слой.":"Лёгкая свободная одежда и головной убор.";JSONArray days=data.optJSONArray("days");if(days!=null&&days.length()>0&&days.optJSONObject(0)!=null&&days.optJSONObject(0).optDouble("rain",0)>=50)text+=" Возьмите зонт или дождевик.";if(current.optDouble("wind_speed_10m",0)>=7)text+=" При сильном ветре пригодится ветровка.";return text;}
    static void weather(MainActivity a,JSONObject data)throws Exception{JSONArray days=data.getJSONArray("days");TextView title=a.label("Температура по дням",19);a.page.addView(title);a.page.addView(new WeatherLine(a,days),new LinearLayout.LayoutParams(-1,a.dp(280)));LinearLayout card=a.column();card.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(14));card.setBackground(a.surface(MainActivity.PANEL,18,true));card.addView(a.label("Что надеть",18));card.addView(a.label(clothing(data),15));a.page.addView(card);}
    static final class WeatherLine extends View{
        final MainActivity a;final JSONArray days;final Paint paint=new Paint(3);
        WeatherLine(MainActivity a,JSONArray days){super(a);this.a=a;this.days=days;setBackground(a.surface(MainActivity.PANEL,18,true));setContentDescription("График минимальной и максимальной температуры на неделю");}
        int selected=0;
        @Override public boolean onTouchEvent(android.view.MotionEvent event){if(event.getAction()==android.view.MotionEvent.ACTION_UP&&days.length()>1){float left=a.dp(36),width=getWidth()-a.dp(58);selected=Math.max(0,Math.min(days.length()-1,Math.round((event.getX()-left)/width*(days.length()-1))));invalidate();performClick();return true;}return true;}
        @Override public boolean performClick(){super.performClick();return true;}
        protected void onDraw(Canvas canvas){super.onDraw(canvas);int count=days.length();if(count<2)return;float left=a.dp(36),right=getWidth()-a.dp(22),top=a.dp(76),bottom=getHeight()-a.dp(62);double min=Double.POSITIVE_INFINITY,max=Double.NEGATIVE_INFINITY;for(int n=0;n<count;n++){JSONObject d=days.optJSONObject(n);if(d==null)return;for(String key:new String[]{"min","max"}){double t=d.optDouble(key,Double.NaN);if(!Double.isFinite(t))return;min=Math.min(min,t);max=Math.max(max,t);}}min=Math.floor(min-2);max=Math.ceil(max+2);double range=Math.max(6,max-min);paint.setTypeface(a.face);paint.setTextSize(a.dp(11));paint.setStrokeWidth(a.dp(1));for(int n=0;n<4;n++){float y=top+(bottom-top)*n/3;paint.setColor(MainActivity.BORDER);canvas.drawLine(left,y,right,y,paint);paint.setColor(MainActivity.MUTED);canvas.drawText(Math.round(min+range*(1-n/3d))+"°",a.dp(5),y+a.dp(4),paint);}int[] colors={MainActivity.TEAL,0xffefbb88};String[] keys={"max","min"};for(int series=0;series<2;series++){Path path=new Path();for(int n=0;n<count;n++){float x=left+(right-left)*n/(count-1),y=bottom-(float)((days.optJSONObject(n).optDouble(keys[series])-min)/range)*(bottom-top);if(n==0)path.moveTo(x,y);else path.lineTo(x,y);}if(series==0){Path fill=new Path(path);fill.lineTo(right,bottom);fill.lineTo(left,bottom);fill.close();paint.setShader(new LinearGradient(0,top,0,bottom,0x339fe4ce,0x009fe4ce,Shader.TileMode.CLAMP));canvas.drawPath(fill,paint);paint.setShader(null);}paint.setColor(colors[series]);paint.setStrokeWidth(a.dp(2));paint.setStyle(Paint.Style.STROKE);canvas.drawPath(path,paint);paint.setStyle(Paint.Style.FILL);for(int n=0;n<count;n++){float x=left+(right-left)*n/(count-1),y=bottom-(float)((days.optJSONObject(n).optDouble(keys[series])-min)/range)*(bottom-top);canvas.drawCircle(x,y,a.dp(n==selected?5:3),paint);}}
            MobileFeatures features=new MobileFeatures(a);paint.setTextAlign(Paint.Align.CENTER);for(int n=0;n<count;n++){float x=left+(right-left)*n/(count-1);JSONObject day=days.optJSONObject(n);android.graphics.drawable.Drawable icon=a.getDrawable(features.weatherIcon(day.optInt("code",-1),true));icon.setTint(day.optInt("code",-1)==0?0xffefbb88:MainActivity.TEAL);icon.setBounds((int)x-a.dp(10),a.dp(46),(int)x+a.dp(10),a.dp(66));icon.draw(canvas);String date=day.optString("date"),label="";try{label=java.time.LocalDate.parse(date).format(java.time.format.DateTimeFormatter.ofPattern("EE",new Locale("ru","RU")));}catch(Exception ignored){}paint.setColor(n==selected?MainActivity.TEAL:MainActivity.MUTED);canvas.drawText(label,x,bottom+a.dp(20),paint);canvas.drawText(date.length()>=10?date.substring(8,10):"",x,bottom+a.dp(36),paint);}paint.setTextAlign(Paint.Align.LEFT);paint.setColor(MainActivity.TEAL);canvas.drawText("Максимум",left,a.dp(24),paint);paint.setColor(colors[1]);canvas.drawText("Минимум",left+a.dp(104),a.dp(24),paint);JSONObject day=days.optJSONObject(Math.min(selected,count-1));String detail=day.optString("date")+"   "+Math.round(day.optDouble("min"))+"° … "+Math.round(day.optDouble("max"))+"°";paint.setColor(MainActivity.WHITE);paint.setTextAlign(Paint.Align.CENTER);canvas.drawText(detail,getWidth()/2f,getHeight()-a.dp(8),paint);paint.setTextAlign(Paint.Align.LEFT);setContentDescription("Температура: "+detail+". Нажмите на день, чтобы выбрать его.");}

    }
    static void timer(MainActivity a){
        TimerDial dial=new TimerDial(a);a.page.addView(dial,new LinearLayout.LayoutParams(-1,a.dp(270)));
        LinearLayout presets=new LinearLayout(a);for(int n:new int[]{1,5,10,25}){Button b=a.button(n+" мин",()->start(a,n*60000L));presets.addView(b,new LinearLayout.LayoutParams(0,-2,1));}a.page.addView(presets);
        EditText minutes=a.field("Своя длительность · минуты","5",false);minutes.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);
        a.action("Запустить",()->{try{int n=Integer.parseInt(minutes.getText().toString());if(n<1||n>1440)throw new Exception("Введите от 1 до 1440 минут");start(a,n*60000L);}catch(Exception e){a.error(e.getMessage());}});
        a.action("Пауза / продолжить",()->{long end=a.prefs.getLong("timerEnd",0);if(end>0){a.prefs.edit().putLong("timerPaused",Math.max(0,end-System.currentTimeMillis())).putLong("timerEnd",0).apply();ReminderReceiver.cancel(a,"timer");}else{long remaining=a.prefs.getLong("timerPaused",0);if(remaining>0){long deadline=System.currentTimeMillis()+remaining;a.prefs.edit().putLong("timerEnd",deadline).putLong("timerPaused",0).apply();ReminderReceiver.alarm(a,"timer","Таймер завершён",deadline);}}dial.invalidate();});
        a.action("Сбросить",()->{a.prefs.edit().putLong("timerEnd",0).putLong("timerPaused",0).apply();ReminderReceiver.cancel(a,"timer");dial.invalidate();});a.action("Разрешения уведомлений",a::notificationPermissions);a.text("Таймер продолжит работать в других разделах. Уведомление зависит от разрешений Android.");
    }
    static void start(MainActivity a,long duration){long end=System.currentTimeMillis()+duration;a.prefs.edit().putLong("timerEnd",end).putLong("timerTotal",duration).putLong("timerPaused",0).apply();ReminderReceiver.alarm(a,"timer","Таймер завершён",end);}
    static final class TimerDial extends View{
        final MainActivity a;final Paint p=new Paint(3);final Handler handler=new Handler(Looper.getMainLooper());final Runnable tick=new Runnable(){public void run(){invalidate();handler.postDelayed(this,1000);}};
        TimerDial(MainActivity a){super(a);this.a=a;setContentDescription("Круговой таймер");}
        protected void onAttachedToWindow(){super.onAttachedToWindow();handler.post(tick);}protected void onDetachedFromWindow(){handler.removeCallbacks(tick);super.onDetachedFromWindow();}
        protected void onDraw(Canvas c){super.onDraw(c);long end=a.prefs.getLong("timerEnd",0),remaining=end>0?Math.max(0,end-System.currentTimeMillis()):a.prefs.getLong("timerPaused",0),total=Math.max(1,a.prefs.getLong("timerTotal",300000));float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(cx,cy)-a.dp(28);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(a.dp(8));p.setColor(MainActivity.PANEL);c.drawCircle(cx,cy,r,p);p.setColor(MainActivity.TEAL);p.setStrokeCap(Paint.Cap.ROUND);c.drawArc(cx-r,cy-r,cx+r,cy+r,-90,360*Math.min(1,remaining/(float)total),false,p);p.setStyle(Paint.Style.FILL);p.setTypeface(a.face);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(a.dp(42));long seconds=(remaining+999)/1000;String text=String.format(Locale.ROOT,"%02d:%02d",seconds/60,seconds%60);c.drawText(text,cx,cy+a.dp(12),p);p.setColor(MainActivity.MUTED);p.setTextSize(a.dp(13));c.drawText(end>System.currentTimeMillis()?"Время идёт":end>0?"Время вышло":remaining>0?"На паузе":"Готов к запуску",cx,cy+a.dp(42),p);}
    }
}
